/* Paisa service worker. Generated by scripts/build-web.js — do not edit dist/sw.js. */

const VERSION = "__PAISA_VERSION__";
const PRECACHE = ["__PAISA_PRECACHE__"];
const CACHE = `paisa-shell-${VERSION}`;
const SHELL = '/index.html';

self.addEventListener('install', (event) => {
  // No skipWaiting(): a new version takes over only when every window of the
  // old one has closed, so a migration never runs under a half-updated app.
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(PRECACHE)));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys.filter((key) => key.startsWith('paisa-shell-') && key !== CACHE).map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    // Single-page app: every navigation is the cached shell. Offline-first.
    event.respondWith(caches.match(SHELL, { cacheName: CACHE }).then((cached) => cached || fetch(request)));
    return;
  }

  event.respondWith(caches.match(request, { cacheName: CACHE }).then((cached) => cached || fetch(request)));
});
